(window.RW_DISPLAY = window.RW_DISPLAY || {})["command-of-evidence_8"] = [{"id":"94c726fb","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Millions of Metric Tons of Copper Mined in 1995 and 2020 Country 1995 2020 Canada 0.73 0.59 Indonesia 0.44 0.51 Kazakhstan 0.26 0.55 Chile 2.49 5.73 While doing research for a paper about copper mining, a student finds a table with information about four different countries. The student notes that the country that mined 0.55 million metric tons of copper in 2020 had mined ______","passage_lines":[{"type":"table","title":"Mined in 1995 and 2020","headers":["Country","1995","2020"],"rows":[["Millions of Metr","ric Tons of","Copper"],["Canada","0.73","0.59"],["Indonesia","0.44","0.51"],["Kazakhstan","0.26","0.55"],["Chile","2.49","5.73"]]},{"type":"text","text":"Millions of Metric Tons of Copper Mined in 1995 and 2020 Country 1995 2020 Canada 0.73 0.59 Indonesia 0.44 0.51 Kazakhstan 0.26 0.55 Chile 2.49 5.73 While doing research for a paper about copper mining, a student finds a table with information about four different countries. The student notes that the country that mined 0.55 million metric tons of copper in 2020 had mined ______"}],"question":"Which choice most effectively uses data from the table to complete the statement?","choices":["0.59 million metric tons of copper in 1995.","0.44 million metric tons of copper in 1995.","0.26 million metric tons of copper in 1995.","2.49 million metric tons of copper in 1995."],"underline":null,"underline_segments":["Mined in","in 1995 and","2020"]},{"id":"7a1877be","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Hard","context":"Information and Ideas · Command of Evidence","passage":"Nucleobase Concentrations from Murchison Meteorite and Soil Samples in Parts per Billion Nucleobase Murchison meteorite sample 1 Murchison meteorite sample 2 Murchison soil sample Isoguanine 0.5 0.04 not detected Purine 0.2 0.02 not detected Xanthine 39 3 1 Adenine 15 1 40 Hypoxanthine 24 1 2 Employing high-performance liquid chromatography — a process that uses pressurized water to separate material into its component molecules — astrochemist Yashiro Oba and colleagues analyzed two samples of the Murchison meteorite that landed in Australia as well as soil from the landing zone of the meteorite to determine the concentrations of various organic molecules. By comparing the relative concentrations of types of molecules known as nucleobases in the Murchison meteorite with those in the soil, the team concluded that there is evidence that the nucleobases in the Murchison meteorite formed in space and are not the result of contamination on Earth.","passage_lines":[{"type":"table","title":"Nucleobase Concentrations from Murchison Meteorite and Soil Samples in Parts per Billion","headers":["Nucleobase","Murchison meteorite sample 1","Murchison meteorite sample 2","Murchison soil sample"],"rows":[["Isoguanine","0.5","0.04","not detected"],["Purine","0.2","0.02","not detected"],["Xanthine","39","3","1"],["Adenine","15","1","40"],["Hypoxanthine","24","1","2"]]},{"type":"text","text":"Employing high-performance liquid chromatography — a process that uses pressurized water to separate material into its component molecules — astrochemist Yashiro Oba and colleagues analyzed two samples of the Murchison meteorite that landed in Australia as well as soil from the landing zone of the meteorite to determine the concentrations of various organic molecules. By comparing the relative concentrations of types of molecules known as nucleobases in the Murchison meteorite with those in the soil, the team concluded that there is evidence that the nucleobases in the Murchison meteorite formed in space and are not the result of contamination on Earth."}],"question":"Which choice best describes data from the table that support the team’s conclusion?","choices":["Isoguanine and purine were detected in both meteorite samples but not in the soil sample.","Adenine and xanthine were detected in both of the meteorite samples and in the soil sample.","Hypoxanthine and purine were detected in both the Murchison meteorite sample 2 and in the soil sample.","Isoguanine and hypoxanthine were detected in the Murchison meteorite sample 1 but not in sample 2."],"underline":null,"underline_segments":["Nucleobase","Concentrations from Murchison","Meteorite and Soil Samples in","in Parts per Billion"]},{"id":"224428ac","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Medium","context":"Information and Ideas · Command of Evidence","passage":"California Condor Populations 2014–2020 400 Number of condors 300 200 100 0 14 15 16 17 18 19 20 20 20 20 20 20 20 20 Year captive wild The California Condor Recovery Program is working to protect this large, rare American vulture from extinction. The program captured 27 wild condors in 1987 in order to protect and breed them. Captive birds have been reintroduced into the wild since 1992. Although the California condor is still a rare species, many biologists claim that the program has been reasonably successful.","passage_lines":[{"type":"chart","note":"[Graph: California Condor Populations, 2014–2020 — not available here]"},{"type":"text","text":"The California Condor Recovery Program is working to protect this large, rare American vulture from extinction. The program captured 27 wild condors in 1987 in order to protect and breed them. Captive birds have been reintroduced into the wild since 1992. Although the California condor is still a rare species, many biologists claim that the program has been reasonably successful."}],"question":"Which choice best describes data from the graph that support the biologists’ claim?","choices":["The number of captive California condors steadily decreased between 2014 and 2020.","The numbers of California condors living both in captivity and in the wild decreased only slightly from 2019 to 2020.","The difference between the number of captive and wild California condors remained relatively steady between 2014 and 2017.","The number of wild California condors increased overall from 2014 to 2020 and exceeded the number of those living in captivity."]},{"id":"4411e15b","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Hard","context":"Information and Ideas · Command of Evidence","passage":"Fiber Characteristics of Mouflon, Navajo-Churro, and Spanish Merino Sheep Type of sheep Diameter of outer coat fibers (in microns) Diameter of inner coat fibers (in microns) Spanish Merino 19 – 24 17 –21 Navajo-Churro 35 or higher 10 –35 Mouflon 150 15 Domestic sheep’s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much softer. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft overall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the marked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a more durable yarn, which Diné (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep reveals that ______","passage_lines":[{"type":"table","title":"Fiber Characteristics of Mouflon, Navajo-Churro, and Spanish Merino Sheep","headers":["Type of sheep","Diameter of outer coat fibers (in microns)","Diameter of inner coat fibers (in microns)"],"rows":[["Spanish Merino","19–24","17–21"],["Navajo-Churro","35 or higher","10–35"],["Mouflon","150","15"]]},{"type":"text","text":"Domestic sheep’s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much softer. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft overall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the marked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a more durable yarn, which Diné (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep reveals that ______"}],"question":"Which choice most effectively uses data from the table to complete the text?","choices":["the selection process that enabled the Navajo-Churro to retain its somewhat coarse outer fiber also resulted in inner fiber that, at its softest, is softer than either the mouflon’s or the Merino’s inner fiber.","the Navajo-Churro more closely resembles its ancestor, the mouflon, in the uniform softness of its inner fiber, while the Merino more closely resembles the mouflon in the variable diameter of its outer fiber.","domestication resulted in a counterintuitive increase in the inner fiber’s minimum diameter, making the inner fiber of the Merino and the Navajo-Churro less suitable for delicate garments than the mouflon’s inner fiber is.","the domestication of the mouflon and the subsequent selection process that produced the Merino and the Navajo-Churro resulted in greater softness of outer and inner fiber alike."],"underline":null,"underline_segments":["Fiber","Fiber Characteristics of Mouflon, Navajo-Churro,","and Spanish Merino Sheep"]},{"id":"c384987b","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Scientists have long believed that giraffes are mostly silent and communicate only visually with one another. But biologist Angela Stöger and her team analyzed hundreds of hours of recordings of giraffes in three European zoos and found that giraffes make a very low-pitched humming sound. The researchers claim that the giraffes use these sounds to communicate when it’s not possible for them to signal one another visually.","question":"Which finding, if true, would most directly support Stöger and her team’s claim?","choices":["Giraffes have an excellent sense of vision and can see in color.","The giraffes only produced the humming sounds at night when they couldn’t see one another.","Wild giraffes have never been recorded making humming sounds.","Researchers observed other animals in European zoos humming."]},{"id":"7dab4d5d","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Hard","context":"Information and Ideas · Command of Evidence","passage":"Mean Attentiveness Scores by Leave Time Condition 600 Mean test score (higher scores indicate greater attentiveness) 540 480 420 360 300 240 180 120 60 0 first second third Test administration no leave 2–4 days leave 1–5 weeks leave To investigate potential cognitive benefits of taking leave from work, psychologist Jan Packer and colleagues conducted a six-month study of Australian university staff members who took no leave from work during the study, took 2 – – 4 days of leave, or took 1 5 weeks of leave. Tests of attentiveness were administered to participants three times during the study: at random for the no-leave staff, and for the rest, one week before their leave, one week following their return to work, and one week after the second test administration. After analyzing the results, the researchers concluded that longer leave times might not confer a greater cognitive benefit than shorter leave times do.","passage_lines":[{"type":"chart","note":"[Graph: Mean Attentiveness Scores by Leave Time Condition — not available here]"},{"type":"text","text":"To investigate potential cognitive benefits of taking leave from work, psychologist Jan Packer and colleagues conducted a six-month study of Australian university staff members who took no leave from work during the study, took 2 – – 4 days of leave, or took 1 5 weeks of leave. Tests of attentiveness were administered to participants three times during the study: at random for the no-leave staff, and for the rest, one week before their leave, one week following their return to work, and one week after the second test administration. After analyzing the results, the researchers concluded that longer leave times might not confer a greater cognitive benefit than shorter leave times do."}],"question":"Which choice best describes data from the graph that support the researchers conclusion?","choices":["In the second test administration, participants who took 2 – 4 days of leave had higher average attentiveness scores than did those who took no leave, but in the third test administration, those who took no leave had higher average scores than those who took 1 – 5 weeks of leave.","In the first test administration, participants who took 2 – 4 days of leave had lower average attentiveness scores than did those who took 1 – 5 weeks of leave and those who took no leave.","In both the second and third test administrations, participants who took 2 – 4 days of leave had higher average attentiveness scores than did participants who took 1 – 5 weeks of leave.","In both the second and third test administrations, participants who took 2 – 4 days of leave had higher average attentiveness scores than did participants who took no leave."]},{"id":"8545ccfe","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Hard","context":"Information and Ideas · Command of Evidence","passage":"Icebergs generally appear to be mostly white or blue, depending on how the ice reflects sunlight. Ice with air bubbles trapped in it looks white because much of the light reflects off the bubbles. Ice without air bubbles usually looks blue because the light travels deep into the ice and only a little of it is reflected. However, some icebergs in the sea around Antarctica appear to be green. One team of scientists hypothesized that this phenomenon is the result of yellow-tinted dissolved organic carbon in Antarctic waters mixing with blue ice to produce the color green.","passage_lines":[{"type":"line","text":"Icebergs generally appear to be mostly white or blue, depending on how the ice reflects sunlight. Ice with air bubbles trapped in it looks white","indent":0},{"type":"line","text":"because much of the light reflects off the bubbles. Ice without air bubbles usually looks blue because the light travels deep into the ice and only","indent":0},{"type":"line","text":"a little of it is reflected. However, some icebergs in the sea around Antarctica appear to be green. One team of scientists hypothesized that this","indent":0},{"type":"line","text":"phenomenon is the result of yellow-tinted dissolved organic carbon in Antarctic waters mixing with blue ice to produce the color green.","indent":0}],"question":"Which finding, if true, would most directly weaken the team’s hypothesis?","choices":["White ice doesn’t change color when mixed with dissolved organic carbon due to the air bubbles in the ice.","Dissolved organic carbon has a stronger yellow color in Antarctic waters than it does in other places.","Blue icebergs and green icebergs are rarely found near each other.","Blue icebergs and green icebergs contain similarly small traces of dissolved organic carbon."]},{"id":"55df0275","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Hard","context":"Information and Ideas · Command of Evidence","passage":"Ablation Rates for Three Elements in Cosmic Dust, by Dust Source Element SPC AST HTC OCC iron 20% 28% 90% 98% potassium 44% 74% 97% 100% sodium 45% 75% 99% 100% Earth’s atmosphere is bombarded by cosmic dust originating from several sources: short-period comets (SPCs), particles from the asteroid belt (ASTs), Halley-type comets (HTCs), and Oort cloud comets (OCCs). Some of the dust’s material vaporizes in the atmosphere in a process called ablation, and the faster the particles move, the higher the rate of ablation. Astrophysicist Juan Diego Carrillo-S ánchez led a team that calculated average ablation rates for elements in the dust (such as iron and potassium) and showed that material in slower-moving SPC or AST dust has a lower rate than the same material in faster-moving HTC or OCC dust. For example, whereas the average ablation rate for iron from AST dust is 28%, the average rate for ______","passage_lines":[{"type":"table","title":"Ablation Rates for Three Elements in Cosmic Dust, by Dust Source","headers":["Element","SPC","AST","HTC","OCC"],"rows":[["iron","20%","28%","90%","98%"],["potassium","44%","74%","97%","100%"],["sodium","45%","75%","99%","100%"]]},{"type":"text","text":"Earth’s atmosphere is bombarded by cosmic dust originating from several sources: short-period comets (SPCs), particles from the asteroid belt (ASTs), Halley-type comets (HTCs), and Oort cloud comets (OCCs). Some of the dust’s material vaporizes in the atmosphere in a process called ablation, and the faster the particles move, the higher the rate of ablation. Astrophysicist Juan Diego Carrillo-S ánchez led a team that calculated average ablation rates for elements in the dust (such as iron and potassium) and showed that material in slower-moving SPC or AST dust has a lower rate than the same material in faster-moving HTC or OCC dust. For example, whereas the average ablation rate for iron from AST dust is 28%, the average rate for ______"}],"question":"Which choice most effectively uses data from the table to complete the example?","choices":["iron from SPC dust is 20%.","sodium from OCC dust is 100%.","iron from HTC dust is 90%.","sodium from AST dust is 75%."],"underline":"Dust Source","underline_segments":["Dust Source"]},{"id":"0fc0a773","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"The Minneapolis Institute of Art in Minneapolis, Minnesota, has over 90,000 works of art. Digital images of thousands of those works have been put online through the museum’s website and the Google Arts & Culture project. One of the images is of Mississippi Delta, a drawing by Siah Armajani. In a paper,","passage_lines":[{"type":"line","text":"The Minneapolis Institute of Art in Minneapolis, Minnesota, has over 90,000 works of art. Digital images of thousands of those works have been","indent":0},{"type":"line","text":"put online through the museum’s website and the Google Arts & Culture project. One of the images is of Mississippi Delta, a drawing by Siah","indent":0},{"type":"line","text":"Armajani. In a paper, a student claims that putting a work from the museum online increases the number of people who experience that work.","indent":0}],"question":"Which finding, if true, would most directly support the underlined claim?","choices":["The Minneapolis Institute of Art has several works by Siah Armajani.","Many people who have been to Minneapolis say that the Minneapolis Institute of Art is worth visiting.","Mississippi Delta has been praised by some art critics.","Each year, more people access the online image of Mississippi Delta than visit the Minneapolis Institute of Art in person."],"underline":"putting a work from the museum online increases the number of people who experience that work.","underline_segments":["putting a work from the museum online increases the number of people who experience that work."]},{"id":"a04807d8","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Number of Museum Visits (in Millions) from 2016 to 2019 Museum 2016 2017 2018 2019 National Museum of the American Indian 1.1 1.2 1.1 0.96 National Museum of African American History and Culture 0.73 2.4 1.9 2.0 A student is researching the number of visits each year to two museums, the National Museum of the American Indian and the National Museum of African American History and Culture. Of the four years included in the table, the year when both museums had the highest number of visits was ______","passage_lines":[{"type":"table","title":"Number of Museum Visits (in Millions) from 2016 to 2019","headers":["Museum","2016","2017","2018","2019"],"rows":[["National Museum of the American Indian","1.1","1.2","1.1","0.96"],["National Museum of African American History and Culture","0.73","2.4","1.9","2.0"]]},{"type":"text","text":"A student is researching the number of visits each year to two museums, the National Museum of the American Indian and the National Museum of African American History and Culture. Of the four years included in the table, the year when both museums had the highest number of visits was ______"}],"question":"Which choice most effectively uses data from the table to complete the statement?","choices":["2016.","2018.","2019.","2017."],"underline":null,"underline_segments":["Number of Museum Visits (in Millions)","from 2016","to 2019"]},{"id":"25b70215","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Effect of Neighboring Species on Pollinator Visits to Target Species Neighboring species Target species Effect value Virginia spring beauty star chickweed 0.4853 Himalayan balsam marsh woundwort 0.7905 common dandelion cat’s ear −0.6254 Researchers Carolina Laura Morales and Anna Traveset gathered data about flowering plants growing alongside each other in various locations. In each case, the researchers identified one plant as a “target species” and a nearby plant as a “neighboring species.” The researchers then calculated a positive or negative value to show how the neighboring species affected pollinator visits to the target species. One example of a neighboring species with a negative effect value is the ______","passage_lines":[{"type":"table","title":"Effect of Neighboring Species on Pollinator Visits to Target Species","headers":["Neighboring species","Target species","Effect value"],"rows":[["Virginia spring beauty","star chickweed","0.4853"],["Himalayan balsam","marsh woundwort","0.7905"],["common dandelion","cat’s ear","−0.6254"]]},{"type":"text","text":"Researchers Carolina Laura Morales and Anna Traveset gathered data about flowering plants growing alongside each other in various locations. In each case, the researchers identified one plant as a “target species” and a nearby plant as a “neighboring species.” The researchers then calculated a positive or negative value to show how the neighboring species affected pollinator visits to the target species. One example of a neighboring species with a negative effect value is the ______"}],"question":"Which choice most effectively uses data from the table to complete the example?","choices":["Himalayan balsam.","common dandelion.","star chickweed.","Virginia spring beauty."],"underline":null,"underline_segments":["Target","Target Species"]},{"id":"bc1b8a42","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Percentage of Bus Shelters with Shade in a County by Areas’ Highest Average Summer Surface Temperature Highest average surface temperature (Fahrenheit) Percentage of bus stops with shaded shelter 90.2° 15% 97.7° 22% 102.7° 24% 111.2° 28% 125.6° 29% A student is researching a bus system in a large county where surface temperatures vary by area and are hot in the summer. The student claims that all areas of the county should have more bus stops with shaded shelter, noting that the highest percentage of bus stops with shaded shelter for any area is only ______","passage_lines":[{"type":"table","title":"Percentage of Bus Shelters with Shade in a County by Areas’ Highest Average Summer Surface Temperature","headers":["Highest average surface temperature (Fahrenheit)","Percentage of bus stops with shaded shelter"],"rows":[["90.2°","15%"],["97.7°","22%"],["102.7°","24%"],["111.2°","28%"],["125.6°","29%"]]},{"type":"text","text":"A student is researching a bus system in a large county where surface temperatures vary by area and are hot in the summer. The student claims that all areas of the county should have more bus stops with shaded shelter, noting that the highest percentage of bus stops with shaded shelter for any area is only ______"}],"question":"Which choice most effectively uses data from the table to complete the student’s claim?","choices":["50%.","15%.","90%.","29%."],"underline":"Temperature","underline_segments":["Temperature"]},{"id":"1db1a9a6","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Medium","context":"Information and Ideas · Command of Evidence","passage":"Cantaloupe Yield 45 40 Yield (pounds per acre) 35 30 25 20 15 10 5 0 2017 2018 2019 Year control nitrogen fertilizer To test the effects of a nitrogen fertilizer on cantaloupe production, researchers grew cantaloupe plants and harvested their fruit over three years. In each year, half the plants were grown using a nitrogen fertilizer, and the other half were grown using a control fertilizer that contained no nitrogen. The researchers concluded that the nitrogen fertilizer increases cantaloupe yield.","passage_lines":[{"type":"chart","note":"[Graph: Cantaloupe Yield — not available here]"},{"type":"text","text":"To test the effects of a nitrogen fertilizer on cantaloupe production, researchers grew cantaloupe plants and harvested their fruit over three years. In each year, half the plants were grown using a nitrogen fertilizer, and the other half were grown using a control fertilizer that contained no nitrogen. The researchers concluded that the nitrogen fertilizer increases cantaloupe yield."}],"question":"Which choice best describes data in the graph that support the researchers conclusion?","choices":["In every year of the experiment, plants treated with the nitrogen fertilizer had a yield of at least 30 pounds per acre.","In every year of the experiment, plants treated with the nitrogen fertilizer had a greater yield than did plants treated with the control fertilizer.","The 2018 yield for plants treated with the control fertilizer was greater than was the 2019 yield for plants treated with the nitrogen fertilizer.","The yield for plants treated with the nitrogen fertilizer increased from 2017 to 2018."]},{"id":"a0203977","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Medium","context":"Information and Ideas · Command of Evidence","passage":"Annual Spending by International Tourists in Four Countries (in billions of US dollars) Country 2016 2017 2018 South Korea $21.0 $17.2 $23.1 Japan $33.5 $37.0 $45.3 Thailand $48.5 $57.1 $61.4 Malaysia $19.7 $20.3 $21.8 One measure of international tourism is how much money visitors from abroad spend in a country. A student writing a report about tourism in several Asian countries notes that among the countries in the table, most had annual increases in international tourism revenue in 2017 and 2018, but that trend wasn’t universal. For example, ______","passage_lines":[{"type":"table","title":"Annual Spending by International Tourists in Four Countries (in billions of US dollars)","headers":["Country","2016","2017","2018"],"rows":[["South Korea","$21.0","$17.2","$23.1"],["Japan","$33.5","$37.0","$45.3"],["Thailand","$48.5","$57.1","$61.4"],["Malaysia","$19.7","$20.3","$21.8"]]},{"type":"text","text":"One measure of international tourism is how much money visitors from abroad spend in a country. A student writing a report about tourism in several Asian countries notes that among the countries in the table, most had annual increases in international tourism revenue in 2017 and 2018, but that trend wasn’t universal. For example, ______"}],"question":"Which choice most effectively uses data from the table to complete the example?","choices":["in each year shown, the revenue from tourism by residents of those countries was greater than the revenue from international tourism.","Japan’s international tourism revenue was higher in 2016 than it was in 2018.","South Korea’s annual international tourism revenue decreased from 2016 to 2017.","in each year shown, Thailand had higher international tourism income than any of the other countries."],"underline":null,"underline_segments":["Four Countries","(in billions","billions of US","dollars)"]},{"id":"4042ff0b","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"Easy","context":"Information and Ideas · Command of Evidence","passage":"Comfort Ratings and Temperature-Adjustment Preferences from One Survey Participant Comfort rating Preferred temperature adjustment 20 −2 Cooler 1 1 Cooler 21 1 Cooler Nan Gao and her team conducted multiple surveys to determine participants’ levels of comfort in a room where the temperature was regulated by a commercial climate control system. Participants filled out surveys several times a day to indicate their level of comfort on a scale from −3 (very cold) to +3 (very hot), with 0 indicating neutral (neither warm nor cool), and to indicate how they would prefer the temperature to be adjusted. The table shows three participants’ responses in one of the surveys. According to the table, all three participants wanted the room to be cooler, ______","passage_lines":[{"type":"table","title":"Comfort Ratings and Temperature-Adjustment Preferences from One Survey","headers":["Participant","Comfort rating","Preferred temperature adjustment"],"rows":[["20","−2","Cooler"],["1","1","Cooler"],["21","1","Cooler"]]},{"type":"text","text":"Nan Gao and her team conducted multiple surveys to determine participants’ levels of comfort in a room where the temperature was regulated by a commercial climate control system. Participants filled out surveys several times a day to indicate their level of comfort on a scale from −3 (very cold) to +3 (very hot), with 0 indicating neutral (neither warm nor cool), and to indicate how they would prefer the temperature to be adjusted. The table shows three participants’ responses in one of the surveys. According to the table, all three participants wanted the room to be cooler, ______"}],"question":"Which choice most effectively uses data from the table to complete the statement?","choices":["and they each reported the same level of comfort.","even though each participant’s ratings varied throughout the day.","but participant 20 reported feeling significantly colder than the other two participants did.","but participant 1 reported feeling warmer than the other two participants did."],"underline":null,"underline_segments":["One","One Survey"]}];
